function trunkSvg() {
  // tapered curved trunk along a cubic spine
  const P = [BASE, [146, 252], [196, 160], CROWN];
  const at = (t) => {
    const u = 1 - t;
    return [
      u * u * u * P[0][0] + 3 * u * u * t * P[1][0] + 3 * u * t * t * P[2][0] + t * t * t * P[3][0],
      u * u * u * P[0][1] + 3 * u * u * t * P[1][1] + 3 * u * t * t * P[2][1] + t * t * t * P[3][1],
    ];
  };
  const L = [];
  const R = [];
  const LL = [];
  const rings = [];
  const N = 40;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const p = at(t);
    const q = at(Math.min(1, t + 0.01));
    const o = at(Math.max(0, t - 0.01));
    let tx = q[0] - o[0];
    let ty = q[1] - o[1];
    const tl = Math.hypot(tx, ty);
    tx /= tl;
    ty /= tl;
    const nx = -ty;
    const ny = tx;
    const w = 7.5 - 3.2 * t + (t < 0.06 ? (0.06 - t) * 40 : 0);
    L.push([p[0] - nx * w, p[1] - ny * w]);
    R.push([p[0] + nx * w, p[1] + ny * w]);
    LL.push([p[0] - nx * w * 0.1, p[1] - ny * w * 0.1]);
    if (i % 2 === 1 && t < 0.97) rings.push(`M${f(p[0] - nx * w)} ${f(p[1] - ny * w)}Q${f(p[0] + ty * 1.6)} ${f(p[1] - tx * 1.6 + 2.2)} ${f(p[0] + nx * w)} ${f(p[1] + ny * w)}`);
  }
  // nx,ny points right of travel: as the trunk goes up and right, "R" is the
  // shaded side away from the sun.
  return (
    `<path d="${poly([...L, ...R.reverse()])}" fill="${BARK}"/>` +
    `<path d="${poly([...L, ...LL.reverse()])}" fill="${BARK_L}"/>` +
    `<path d="${rings.join('')}" fill="none" stroke="${BARK_R}" stroke-width="1.3" stroke-linecap="round" opacity=".75"/>`
  );
}

